`default_nettype none

// ============================================================================
// dpti_clk_gen.sv
//
// The FT2232H interface clock: CLKOUT (Y18, IO_L13P_T2_MRCC_14) regenerated by
// an MMCM whose feedback cancels the clock-tree insertion delay, plus the
// controller that keeps the MMCM locked through CLKOUT stopping and starting.
//
// WHY AN MMCM (and not IBUF -> BUFG as before)
//   The FT2232H changes RXF#, TXE# and read DATA 1 .. 7.15 ns after its CLKOUT
//   edge and needs RD#, OE#, WR# and write DATA 8 ns before the next one, hold
//   0 (FT_000061 v2.10 Table 4.1).  Through IBUF -> BUFG the register clock
//   arrives about 5.4 ns after the pad (K16 STA of the previous bitstream).  That
//   puts the input capture edge inside the chip's 1 .. 7.15 ns change window --
//   the R4b replay lost 4835 bytes to it -- and makes the outputs reach the
//   chip about 9.7 ns after its edge, past the 8.67 ns setup point.
//
// FEEDBACK TOPOLOGY AND COMPENSATION
//   CLKFBOUT -> BUFG -> CLKFBIN, with CLKOUT0 on a second BUFG.  Feeding back
//   through a BUFG makes the MMCM align the *output* of a global buffer -- the
//   clock as the IOB registers see it -- with CLKIN at the pad, so the IBUF,
//   BUFG and clock-tree delays drop out.  For that arrangement the MMCM's
//   compensation mode is ZHOLD (UG472; also the MMCME2_ADV default, and the
//   value Vivado keeps only when the feedback really is a BUFG).  The other
//   modes do not fit: INTERNAL (CLKFBOUT straight to CLKFBIN) leaves the whole
//   tree delay in place, BUF_IN is for a CLKIN that already comes off a BUFG,
//   EXTERNAL needs a board feedback trace.
//   This is the design intent, not the proof.  dma_top_build.tcl refuses a
//   routed design whose MMCM COMPENSATION is not ZHOLD, and the I/O setup and
//   hold slacks against nexys_video_dpti_timing.xdc are what decide.
//
// PHASE
//   CLKOUT0_PHASE defaults to 0.  It is a parameter, not a constant, because
//   the right value comes from STA: a negative shift moves the capture and
//   launch edges earlier, which adds input hold and output setup margin and
//   costs input setup (large) and output hold (needs only >= 0).  Change it
//   only when the routed I/O slacks say so, and record the reason.
//
// VCO
//   60 MHz x 15 = 900 MHz, / 15 = 60 MHz; PFD 60 MHz.  900 MHz sits inside
//   the -1 MMCM VCO range (600 .. 1200 MHz, DS181 -- confirm against the
//   current DS181 revision; Vivado's DRC checks it at implementation).
//
// LOCK CONTROLLER (clk_sys, free-running from configuration)
//   CLKOUT is not always present: the host switches the chip into sync-FIFO
//   mode when it opens the device and back out when it closes it
//   (runtime/dpti_ftdi.cpp), and whether CLKOUT keeps running outside sync
//   mode is not documented.  This controller is correct either way:
//     * the MMCM is reset once after configuration;
//     * after RST is released it waits LOCK_TIMEOUT_CYC for LOCKED, and if
//       LOCKED does not come, resets and tries again, indefinitely;
//     * once locked, a falling LOCKED or a rising CLKINSTOPPED resets it at
//       once.  This matters: when CLKIN stops, an MMCM's VCO keeps running
//       (Xilinx's own MMCME2_ADV model free-runs it), so without the reset the
//       DPTI domain would go on being clocked by a clock nobody controls;
//     * hold_rst keeps it in reset (dpti_link_ctrl uses this to freeze the
//       DPTI domain while the ui_clk side drains what is already across).
//   While RST is high the MMCM drives its outputs low, so clk_dpti simply
//   stops; it never produces an extra rising edge.
//   LOCK_TIMEOUT_CYC must exceed the MMCM's maximum lock time (DS181
//   MMCM_LOCK_MAX) -- the default, 1.31 ms, is a generous multiple of it.
//
// locked is the MMCM's own LOCKED, unsynchronized: it is meant for
// asynchronous resets (pads safe without a clock) and for synchronizers in the
// domains that read it.
// ============================================================================

module dpti_clk_gen #(
    parameter real    CLKOUT0_PHASE    = 0.0,       // degrees; see PHASE above
    parameter         BANDWIDTH        = "OPTIMIZED",
    parameter integer RST_PULSE_CYC    = 16,        // clk_sys cycles of RST
    parameter integer LOCK_TIMEOUT_CYC = 131072     // clk_sys cycles to wait for LOCKED
) (
    input  wire       clk_sys,          // free-running 100 MHz (BUFG)
    input  wire       clkout_pad,       // FT2232H CLKOUT, straight from the port
    input  wire       hold_rst,         // any domain; synchronized here

    output wire       clk_dpti,         // BUFG, aligned to clkout_pad
    output wire       locked,           // MMCM LOCKED, asynchronous
    output reg  [7:0] mmcm_reset_count  // clk_sys; saturating, observation only
);

    // ------------------------------------------------------------------
    // Clock path.
    // ------------------------------------------------------------------
    wire clkin_ibuf;
    wire clkfb_raw, clkfb_bufg;
    wire clk0_raw;
    wire clkinstopped;
    reg  mmcm_rst = 1'b1;

    IBUF u_ibuf (.I(clkout_pad), .O(clkin_ibuf));

    MMCME2_ADV #(
        .BANDWIDTH          (BANDWIDTH),
        .COMPENSATION       ("ZHOLD"),
        .CLKIN1_PERIOD      (16.667),
        .DIVCLK_DIVIDE      (1),
        .CLKFBOUT_MULT_F    (15.000),
        .CLKFBOUT_PHASE     (0.000),
        .CLKOUT0_DIVIDE_F   (15.000),
        .CLKOUT0_DUTY_CYCLE (0.500),
        .CLKOUT0_PHASE      (CLKOUT0_PHASE),
        .REF_JITTER1        (0.010),
        .STARTUP_WAIT       ("FALSE")
    ) u_mmcm (
        .CLKIN1       (clkin_ibuf),
        .CLKIN2       (1'b0),
        .CLKINSEL     (1'b1),
        .CLKFBIN      (clkfb_bufg),
        .CLKFBOUT     (clkfb_raw),
        .CLKFBOUTB    (),
        .CLKOUT0      (clk0_raw),
        .CLKOUT0B     (),
        .CLKOUT1      (),
        .CLKOUT1B     (),
        .CLKOUT2      (),
        .CLKOUT2B     (),
        .CLKOUT3      (),
        .CLKOUT3B     (),
        .CLKOUT4      (),
        .CLKOUT5      (),
        .CLKOUT6      (),
        .DADDR        (7'd0),
        .DCLK         (1'b0),
        .DEN          (1'b0),
        .DI           (16'd0),
        .DO           (),
        .DRDY         (),
        .DWE          (1'b0),
        .PSCLK        (1'b0),
        .PSEN         (1'b0),
        .PSINCDEC     (1'b0),
        .PSDONE       (),
        .LOCKED       (locked),
        .CLKINSTOPPED (clkinstopped),
        .CLKFBSTOPPED (),
        .PWRDWN       (1'b0),
        .RST          (mmcm_rst)
    );

    BUFG u_bufg_fb  (.I(clkfb_raw), .O(clkfb_bufg));
    BUFG u_bufg_out (.I(clk0_raw),  .O(clk_dpti));

    // ------------------------------------------------------------------
    // Lock controller.
    // ------------------------------------------------------------------
    localparam [1:0] S_RST    = 2'd0;
    localparam [1:0] S_WAIT   = 2'd1;
    localparam [1:0] S_LOCKED = 2'd2;

    localparam integer CW = $clog2(LOCK_TIMEOUT_CYC + 1);

    (* ASYNC_REG = "TRUE" *) reg [1:0] locked_s  = 2'b00;
    (* ASYNC_REG = "TRUE" *) reg [1:0] stopped_s = 2'b00;
    (* ASYNC_REG = "TRUE" *) reg [1:0] hold_s    = 2'b11;

    reg [1:0]    state = S_RST;
    reg [CW-1:0] cnt   = {CW{1'b0}};

    initial mmcm_reset_count = 8'd0;

    always @(posedge clk_sys) begin
        locked_s  <= {locked_s[0],  locked};
        stopped_s <= {stopped_s[0], clkinstopped};
        hold_s    <= {hold_s[0],    hold_rst};

        case (state)

        S_RST: begin
            mmcm_rst <= 1'b1;
            if (cnt < RST_PULSE_CYC[CW-1:0])
                cnt <= cnt + 1'b1;
            else if (!hold_s[1]) begin
                mmcm_rst <= 1'b0;
                cnt      <= {CW{1'b0}};
                state    <= S_WAIT;
            end
        end

        S_WAIT: begin
            if (hold_s[1] || cnt == LOCK_TIMEOUT_CYC[CW-1:0]) begin
                mmcm_rst <= 1'b1;
                cnt      <= {CW{1'b0}};
                state    <= S_RST;
                if (mmcm_reset_count != 8'hFF)
                    mmcm_reset_count <= mmcm_reset_count + 8'd1;
            end
            else if (locked_s[1])
                state <= S_LOCKED;
            else
                cnt <= cnt + 1'b1;
        end

        S_LOCKED: begin
            if (hold_s[1] || !locked_s[1] || stopped_s[1]) begin
                mmcm_rst <= 1'b1;
                cnt      <= {CW{1'b0}};
                state    <= S_RST;
                if (mmcm_reset_count != 8'hFF)
                    mmcm_reset_count <= mmcm_reset_count + 8'd1;
            end
        end

        default: begin
            mmcm_rst <= 1'b1;
            cnt      <= {CW{1'b0}};
            state    <= S_RST;
        end

        endcase
    end

endmodule

`default_nettype wire
